// Writes deploy/nginx/sbayraktar-redirects.conf from lib/projects.ts.
// deploy/yukle.sh uploads it to /etc/nginx/snippets/ and the vhost includes it.
import { writeFile } from 'node:fs/promises'
import { redirects, fallback } from './redirects.mjs'

const lines = [
    '# Generated by scripts/nginx-redirects.mjs. Do not edit by hand.',
    ...redirects.map((r) => `location = ${r.from} { return 301 ${r.to.startsWith('http') ? r.to : 'https://$host' + r.to}; }`),
    `location ^~ ${fallback.prefix} { return 301 https://$host${fallback.to}; }`,
    '',
]
await writeFile('deploy/nginx/sbayraktar-redirects.conf', lines.join('\n'))
console.log(`[redirects] ${redirects.length} + 1 rules -> deploy/nginx/sbayraktar-redirects.conf`)
